import {escape as e,active,total,atFrame,timecode,animated,sceneSvg} from './render.mjs';
const icons={play:'M7 4l13 8-13 8z',pause:'M8 5v14M16 5v14',back:'M5 4v16M19 5l-10 7 10 7z',next:'M19 4v16M5 5l10 7-10 7z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',down:'M6 9l6 6 6-6',close:'M6 6l12 12M18 6L6 18',check:'M5 12l4 4L19 6',folder:'M3 6h7l2 3h9v11H3z',film:'M4 3h16v18H4zM4 8h16M4 16h16M8 3v18M16 3v18',image:'M3 4h18v16H3zM3 16l6-6 5 5 3-3 4 4M16 8h.01',text:'M4 5h16M12 5v14M8 19h8',shape:'M4 4h16v16H4z',circle:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18',cursor:'M5 3l14 10-7 1-3 7z',hand:'M8 12V5a1 1 0 0 1 2 0v6-8a1 1 0 0 1 2 0v8-7a1 1 0 0 1 2 0v7-5a1 1 0 0 1 2 0v8c0 8-7 7-9 3l-3-5a1 1 0 0 1 2-1z',grid:'M3 3h18v18H3zM3 9h18M3 15h18M9 3v18M15 3v18',undo:'M4 9h9a7 7 0 0 1 0 14M4 9l5-5M4 9l5 5',redo:'M20 9h-9a7 7 0 0 0 0 14M20 9l-5-5M20 9l-5 5',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',unlock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0',branch:'M6 4v16M18 4v3c0 6-12 3-12 9M4 2h4v4H4zM16 2h4v4h-4zM4 18h4v4H4z',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2',review:'M3 4h18v13H9l-6 4z',export:'M12 15V3M7 8l5-5 5 5M4 14v7h16v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M20 4l-2 2M6 18l-2 2',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',search:'M10 3a7 7 0 1 0 0 14 7 7 0 1 0 0-14M15 15l6 6',more:'M5 12h.01M12 12h.01M19 12h.01',audio:'M4 9v6M8 5v14M12 2v20M16 6v12M20 9v6',caption:'M3 5h18v14H3zM10 10a3 3 0 1 0 0 4M18 10a3 3 0 1 0 0 4',graph:'M5 5h4v4H5zM15 3h4v4h-4zM15 17h4v4h-4zM9 7l6-2M9 7l6 12',proposal:'M4 3h6v18H4zM14 3h6v18h-6zM10 12h4',brief:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',story:'M3 4h8v7H3zM15 4h6v7h-6zM3 15h8v5H3zM15 15h6v5h-6z',fullscreen:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5',download:'M12 3v12M7 10l5 5 5-5M4 15v6h16v-6',keyboard:'M3 6h18v12H3zM6 10h1M10 10h1M14 10h1M18 10h1M7 14h10',archive:'M3 4h18v4H3zM5 8v13h14V8M9 12h6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18M12 11v6M12 7h.01',retry:'M20 7a9 9 0 1 0 1 8M21 2v6h-6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]??icons.shape}"/></svg>`;
const button=(action,label,{symbol,cls='',title='',data='',disabled=false}={})=>`<button type="button" data-action="${action}" class="${cls}" ${title?`title="${e(title)}"`:''} ${data} ${disabled?'disabled':''}>${symbol?icon(symbol):''}${label}</button>`;
const ib=(action,symbol,title,data='')=>button(action,'',{symbol,cls:'icon-btn',title,data:`aria-label="${e(title)}" ${data}`});
const uid=p=>`${p}-${crypto.randomUUID().slice(0,12)}`;
const tabs=[['brief','Brief','brief'],['narrative','Narrative','text'],['storyboard','Storyboard','story'],['canvas','Canvas','cursor'],['alternatives','Alternatives','proposal'],['changes','Changes','branch'],['dependencies','Dependencies','graph'],['review','Review','review'],['deliver','Deliver','export']];
const S={csrf:null,projects:[],branches:[],version:null,doc:null,workspace:'canvas',sceneId:'s-1',objectId:null,frame:60,playing:false,playDirection:1,playRate:1,scale:100,timelineZoom:1,guides:false,inspectorTab:'object',resource:localStorage.getItem('sw:project')??'demo-product@main',theme:localStorage.getItem('sw:theme')??'dark',history:[],findings:[],stale:false,busy:false,compare:null};
let toastTimer,anim,lastTime=0,remainder=0,drag=null,pollCount=0;
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',error?8000:3400);}
async function call(operation,parameters={},expected=null,key=crypto.randomUUID()){
 const response=await fetch('/api/call',{method:'POST',headers:{'Content-Type':'application/json','x-sequencewright-csrf':S.csrf},body:JSON.stringify({operation,parameters,expected,key})});const result=await response.json();if(!result.ok){const error=Object.assign(new Error(result.error?.message??'Request failed'),result.error);if(error.code==='StaleReference'){S.stale=true;render();}throw error;}return result.data;
}
async function load(resource=S.resource){
 S.playing=false;cancelAnimationFrame(anim);const current=await call('document.read',{resource});S.resource=resource;S.version=current.version;S.doc=current.document;S.stale=false;
 if(!active(S.doc).some(s=>s.id===S.sceneId))S.sceneId=active(S.doc)[0].id;
 const s=S.doc.scenes.find(s=>s.id===S.sceneId);if(!s.objects.some(o=>o.id===S.objectId&&!o.archived))S.objectId=s.objects.find(o=>!o.archived&&o.kind==='text')?.id??null;
 S.frame=Math.max(0,Math.min(S.frame,total(S.doc)-1));const [projects,branches,history,review]=await Promise.all([call('project.list'),call('branch.list',{resource}),call('history.list',{resource}),call('review.list',{resource})]);S.projects=projects.items;S.workspaceVersion=projects.version;S.branches=branches.items;S.history=history.items;S.findings=review.technicalFindings;localStorage.setItem('sw:project',resource);render();
}
async function mutate(operation,parameters,{resource=S.resource,expected=S.version,followCreated=false,message='Change saved as a new revision'}={}){
 if(S.busy)return;S.busy=true;setSaveState('Saving…');try{const result=await call(operation,parameters,expected);await load(followCreated&&result.metadata.created?result.metadata.created.resource:resource);toast(message);return result;}catch(error){toast(error.message,true);throw error;}finally{S.busy=false;setSaveState('Saved locally');}
}
function setSaveState(text){document.querySelectorAll('[data-save]').forEach(x=>x.textContent=text);}
function scene(){return S.doc.scenes.find(s=>s.id===S.sceneId)??active(S.doc)[0];}
function selected(){return scene().objects.find(o=>o.id===S.objectId&&!o.archived);}
function sceneStart(id){let n=0;for(const s of active(S.doc)){if(s.id===id)return n;n+=s.duration;}return 0;}
function selectScene(id,{keepFrame=false}={}){S.sceneId=id;S.objectId=scene().objects.find(o=>o.kind==='text'&&!o.archived)?.id??null;if(!keepFrame)S.frame=sceneStart(id)+Math.min(60,scene().duration-1);render();}
function durationText(frames){return `${(frames*S.doc.profile.fps.den/S.doc.profile.fps.num).toFixed(1)}s`;}
function badge(text,cls=''){return `<span class="badge ${cls}">${e(text)}</span>`;}
function sceneThumb(s){return `<div class="scene-thumb">${sceneSvg(S.doc,s,Math.min(60,s.duration-1),{resource:S.resource})}</div>`;}
function render(){
 if(!S.doc)return;document.documentElement.dataset.theme=S.theme;const s=scene();const parent=document.querySelector('#app');
 parent.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><img src="/icon.svg" alt=""><span class="wordmark">Sequence<span>wright</span></span></div><span class="divider"></span><button type="button" data-action="project-menu" class="project-title truncate" title="Open or create project">${e(S.doc.title)}${icon('down')}</button><div class="row branch-row">${icon('branch')}<select class="branch-selector" aria-label="Active branch" data-change="branch">${S.branches.map(b=>`<option value="${e(b.version.resource)}" ${b.version.resource===S.resource?'selected':''}>${e(b.name)}</option>`).join('')}</select></div><div class="top-actions"><span class="saved hide-small" data-save>Saved locally</span>${ib('palette','search','Commands (Ctrl+K)')}${button('review','Review',{symbol:'review',cls:'hide-mobile'})}${button('deliver','Deliver',{symbol:'export',cls:'primary'})}</div></header>
 <nav class="tabs" aria-label="Workspaces">${tabs.map(([id,label,symbol])=>button('workspace',label,{symbol,cls:S.workspace===id?'active':'',data:`data-workspace="${id}" aria-current="${S.workspace===id?'page':'false'}"`})).join('')}<span class="right-note">LOCAL WORKSPACE</span></nav>
 <main class="studio" id="workspace"><aside class="explorer" aria-label="Project explorer"><div class="panel-head"><h2>Project</h2>${ib('new-project','plus','Create a project')}</div><select class="project-picker" aria-label="Project" data-change="project">${S.projects.map(p=>`<option value="${e(p.resource)}" ${p.id===S.doc.id?'selected':''}>${e(p.title)}</option>`).join('')}</select><div class="explorer-tools"><input id="scene-search" type="search" placeholder="Find a scene…" aria-label="Find a scene">${ib('add-scene','plus','Add a scene')}</div><div class="scene-list scroll">${active(S.doc).map((sc,i)=>`<button type="button" class="scene-item ${sc.id===S.sceneId?'active':''}" data-action="select-scene" data-id="${e(sc.id)}" draggable="true" data-scene-drag="${e(sc.id)}" aria-label="Scene ${i+1}: ${e(sc.name)}"><div class="scene-thumb">${sceneSvg(S.doc,sc,Math.min(60,sc.duration-1),{resource:S.resource})}<span class="scene-index">${String(i+1).padStart(2,'0')}</span></div><div class="scene-label"><span class="truncate">${e(sc.name)}</span><span class="mono">${durationText(sc.duration)}</span></div><div class="scene-meta"><span>${e(sc.renderer.replaceAll('_',' '))}</span><span class="dot">Design</span></div></button>`).join('')}</div><div class="explorer-foot">${button('assets',`${S.doc.assets.length} assets`,{symbol:'folder',cls:S.workspace==='assets'?'active':''})}<div class="storage-line"><span>${active(S.doc).length} scenes · ${durationText(total(S.doc))}</span><span>Local only</span></div></div></aside><div class="resize-handle left" role="separator" aria-label="Resize project explorer" aria-orientation="vertical" tabindex="0" data-resize="left"></div>
 ${['canvas','timeline'].includes(S.workspace)?canvasWorkspace():pageWorkspace()}
 <div class="resize-handle right" role="separator" aria-label="Resize inspector" aria-orientation="vertical" tabindex="0" data-resize="right"></div>${inspector()}
 </main><footer class="statusbar"><span class="row">${icon('check')} Local document</span><span class="mono">rev ${S.version.revision.slice(0,8)}</span><span class="hide-mobile">${S.doc.profile.width} × ${S.doc.profile.height} · ${S.doc.profile.fps.num/S.doc.profile.fps.den} fps</span><span class="right">Native runtime: not connected</span>${button('theme',S.theme==='dark'?'Light':'Dark',{symbol:S.theme==='dark'?'sun':'moon',title:'Switch theme'})}${ib('help','keyboard','Keyboard shortcuts')}</footer></div>`;
 if(S.stale){const banner=document.createElement('div');banner.className='error-banner';banner.style.position='fixed';banner.style.top='95px';banner.style.left='0';banner.innerHTML=`<span>A newer revision exists. Your unsaved edits have not been applied.</span>${button('reload','Reload current revision',{symbol:'retry'})}`;parent.append(banner);}
 if(S.workspace==='changes'&&S.compare)renderComparison();updatePlayhead();
}
function canvasWorkspace(){const s=scene();return `<section class="center" aria-label="Sequence editor"><div class="canvas-toolbar">${ib('select-tool','cursor','Selection tool')}${ib('add-text','text','Add text')}${ib('add-rect','shape','Add rectangle')}${ib('add-circle','circle','Add circle')}<span class="divider"></span>${ib('undo','undo','Restore previous revision (Ctrl+Z)')}<div class="grow"></div>${button('guides','Guides',{symbol:'grid',cls:S.guides?'active':''})}${button('zoom',`${S.scale}%`,{title:'Cycle canvas zoom'})}${ib('fullscreen','fullscreen','Full screen preview')}</div>
 <div class="canvas-section"><div class="canvas-meta"><span>${e(s.name)} <span class="muted">/ Composition</span></span>${badge('DESIGN PREVIEW','amber')}</div><div class="canvas-wrap"><div class="canvas-art" id="canvas" style="aspect-ratio:${S.doc.profile.width}/${S.doc.profile.height};transform:scale(${S.scale/100})">${sceneSvg(S.doc,s,Math.max(0,S.frame-sceneStart(s.id)),{selected:S.objectId,guides:S.guides,resource:S.resource,interactive:true})}</div></div><p class="canvas-caption">Editable design approximation. Native rendering and text measurement have not run.</p><div class="player"><span class="time"><strong id="current-time">${timecode(S.frame,S.doc.profile.fps)}</strong> <span>/ ${timecode(total(S.doc),S.doc.profile.fps)}</span></span><div class="transport">${ib('previous-scene','back','Previous scene')}${button('play','',{symbol:S.playing?'pause':'play',cls:'icon-btn play',data:'aria-label="Play or pause"'})}${ib('next-scene','next','Next scene')}</div><div class="row">${button('speed',`${S.playRate}×`,{title:'Playback speed'})}${ib('review-frame','review','Comment on current frame')}</div></div></div><div class="resize-timeline" data-resize="timeline" role="separator" aria-label="Resize timeline" aria-orientation="horizontal" tabindex="0"></div>${timeline()}</section>`;}
function timeline(){const px=Math.max(0.45,S.timelineZoom*0.7),width=Math.max(500,total(S.doc)*px);let offset=0;const clips=active(S.doc).map((s,i)=>{const start=offset;offset+=s.duration;return `<button type="button" class="clip ${s.id===S.sceneId?'selected':''}" style="left:${start*px}px;width:${Math.max(20,s.duration*px-3)}px" data-action="select-scene" data-id="${e(s.id)}" draggable="true" data-scene-drag="${e(s.id)}"><b>${String(i+1).padStart(2,'0')} ${e(s.name)}</b><span>${e(s.role)} · ${durationText(s.duration)}</span><i class="trim-handle" data-trim="${e(s.id)}" title="Trim scene duration"></i></button>`;}).join('');const fps=S.doc.profile.fps.num/S.doc.profile.fps.den;const ticks=[];for(let f=0;f<=total(S.doc);f+=Math.round(fps*5))ticks.push(`<span class="tick" style="left:${f*px}px">${Math.round(f/fps)}s</span>`);
 return `<section class="timeline" aria-label="Timeline"><div class="timeline-head"><h2>Sequence timeline</h2>${badge(`${active(S.doc).length} scenes`)}<div class="grow"></div><label class="row muted" for="timeline-zoom">Zoom</label><input id="timeline-zoom" type="range" min="0.5" max="3" step="0.1" value="${S.timelineZoom}" data-change="timeline-zoom" aria-label="Timeline zoom">${ib('captions','caption','Edit captions')}</div><div class="timeline-body" id="timeline-body" data-px="${px}"><div class="ruler"><div class="track-label mono">${S.doc.profile.fps.num/S.doc.profile.fps.den} fps</div><div class="ruler-area" style="width:${width}px" data-scrub>${ticks.join('')}</div></div><div class="track"><div class="track-label">${icon('film')} Picture</div><div class="track-area" style="width:${width}px">${clips}</div></div><div class="track"><div class="track-label">${icon('audio')} Voice</div><div class="track-area" style="width:${width}px"><div class="voice-placeholder">${S.doc.assets.some(a=>a.mime.startsWith('audio/'))?'Audio asset attached — native mix not rendered':'No voice attached · Import an audio asset to begin'}</div></div></div><div class="track"><div class="track-label">${icon('caption')} Captions</div><div class="track-area" style="width:${width}px">${S.doc.captions.map(c=>`<button class="clip caption-clip" type="button" style="left:${c.start*px}px;width:${Math.max(20,(c.end-c.start)*px-3)}px" data-action="edit-caption" data-id="${e(c.id)}">${e(c.text)}</button>`).join('')}</div></div><div class="playhead" id="playhead"></div></div><div class="timeline-foot">Drag scenes to reorder. Drag a clip’s right edge to trim. Space to play. Edits commit on release.</div></section>`;
}
function field(label,name,value,{type='text',min,max,step,area=false,options=null,full=false}={}){return `<label class="field ${full?'full':''}"><span>${e(label)}</span>${area?`<textarea name="${name}" ${name==='text'?'rows="4"':''}>${e(value)}</textarea>`:options?`<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`;}).join('')}</select>`:`<input name="${name}" type="${type}" value="${e(value)}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step!==undefined?`step="${step}"`:''}>`}</label>`;}
function inspector(){
 const s=scene(),o=selected(),scope=o?.id??s.id,lock=S.doc.locks.find(l=>l.scope===scope);
 return `<aside class="inspector" aria-label="Inspector"><div class="inspector-tabs">${button('inspector-object','Object',{cls:S.inspectorTab==='object'?'active':''})}${button('inspector-scene','Scene',{cls:S.inspectorTab==='scene'?'active':''})}${button('inspector-layers','Layers',{cls:S.inspectorTab==='layers'?'active':''})}</div><div class="inspector-content scroll">${S.inspectorTab==='layers'?`<div class="inspector-section"><div class="section-title"><h3>Scene layers</h3>${ib('add-text','plus','Add text')}</div><div class="layer-list">${s.objects.filter(x=>!x.archived).map(x=>button('select-object',e(x.name),{symbol:x.kind==='text'?'text':x.kind==='circle'?'circle':'shape',cls:`layer ${x.id===S.objectId?'active':''}`,data:`data-id="${e(x.id)}"`})).join('')}</div></div>`:S.inspectorTab==='scene'?`<form data-form="scene"><div class="inspector-section"><h3>Scene properties</h3>${field('Name','name',s.name)}${field('Narrative role','role',s.role,{options:['hook','problem','mechanism','evidence','comparison','reveal','payoff','cta']})}<div class="field-grid">${field('Duration (frames)','duration',s.duration,{type:'number',min:1,max:216000})}${field('Background','background',s.background,{type:'color'})}</div>${field('Production route','renderer',s.renderer,{options:[['motion_canvas','Motion Canvas'],['blender','Blender'],['manim','Manim'],['mlt','MLT']]})}${field('Claim review','claimStatus',s.claimStatus,{options:[['unreviewed','Unreviewed'],['supported','Reviewed: supported'],['needs-evidence','Needs evidence']]})}<p class="inspector-note">A production route is intent, not a connected runtime. Shortening duration can require updating captions and keyframes first.</p><button class="primary" type="submit">Apply scene changes</button></div></form>`:o?`<form data-form="object"><div class="inspector-section"><div class="section-title"><h3>${e(o.kind==='text'?'Text object':'Object properties')}</h3>${badge(o.kind)}</div>${field('Layer name','name',o.name)}${o.kind==='text'?field('Text','text',o.text,{area:true}):''}<div class="field-grid">${['x','y','width','height','rotation'].map(k=>field(k[0].toUpperCase()+k.slice(1),k,o[k],{type:'number',min:['width','height'].includes(k)?1:k==='rotation'?-3600:-16384,max:k==='rotation'?3600:16384})).join('')}${field('Opacity (0–1000)','opacity',o.opacity,{type:'number',min:0,max:1000})}${field('Fill','fill',o.fill,{type:'color'})}${o.kind==='text'?field('Font size','fontSize',o.fontSize,{type:'number',min:8,max:512})+field('Weight','weight',o.weight,{options:[['100','Thin'],['300','Light'],['400','Regular'],['500','Medium'],['600','Semibold'],['700','Bold'],['900','Black']].map(([v,l])=>[Number(v),l])}):''}</div><button class="primary" type="submit">Apply object changes</button></div></form><div class="inspector-section"><div class="section-title"><h3>Motion</h3>${ib('keyframe','plus','Add a keyframe')}</div>${o.keyframes.length?o.keyframes.map(k=>`<div class="row"><span class="mono">${k.frame}f</span><span class="grow">${e(k.property)} · ${k.value}</span>${ib('remove-keyframe','close','Remove keyframe',`data-frame="${k.frame}" data-property="${e(k.property)}"`)}</div>`).join(''):'<p class="inspector-note">No keyframes. Add typed motion at the current scene frame.</p>'}<p class="inspector-note">Preview interpolation is approximate. Film export currently accepts two-key opacity fades; other curves remain editable but block that export.</p></div>`:`<div class="empty"><h3>Select an object</h3><p>Select the canvas or a layer to edit its properties.</p>${button('inspector-layers','Show layers')}</div>`}<div class="inspector-section"><div class="section-title"><h3>Revision protection</h3>${icon(lock?'lock':'unlock')}</div><p class="inspector-note">${lock?`Locked by ${e(lock.owner)}: ${e(lock.reason)}`:'Protect this selection from changes by other application roles.'}</p>${button(lock?'unlock':'lock',lock?'Release my lock':'Lock selection',{symbol:lock?'unlock':'lock',disabled:!!lock&&lock.owner!=='local-editor'})}${o?button('archive-object','Archive object',{symbol:'archive',cls:'danger'}):''}</div></div></aside>`;
}
function pageWorkspace(){
 const names={brief:['Start with the idea','A shared brief keeps each editorial decision grounded.'],narrative:['Shape the story','Every scene has a purpose, a claim and a place in the sequence.'],storyboard:['See the whole sequence','Original editable design studies, not native-rendered frames.'],alternatives:['Explore without overwriting','Proposals stay separate until you review and accept them.'],changes:['Keep the decision trail','Revisions are immutable. Restore creates a new revision; nothing is erased.'],dependencies:['Know what is current','Application state is visible here. Canonical Graph admission still requires a Host.'],review:['Review in context','Comments are anchored to an exact revision, scene and frame.'],deliver:['Prepare the handoff','Editable source and caption exports are available. Native media delivery requires a connected renderer.'],assets:['Project assets','Small reference media, with provenance and content digests.'],captions:['Captions and timing','Frame-based half-open intervals preserve the project timebase.']};
 const [title,description]=names[S.workspace]??['Workspace',''];
 const topAction={alternatives:['new-proposal','New proposal','plus'],changes:['fork','New branch','branch'],review:['review-frame','Add comment','plus'],assets:['import-asset','Import asset','plus'],captions:['add-caption','Add caption','plus'],storyboard:['add-scene','Add scene','plus']}[S.workspace];
 return `<section class="workspace-page scroll" aria-label="${e(title)}"><div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${topAction?button(topAction[0],topAction[1],{symbol:topAction[2],cls:'primary'}):''}</div><div class="page-body">${pageContent()}</div></section>`;
}
function pageContent(){
 switch(S.workspace){
 case 'brief':return `<form data-form="brief" class="paper"><div class="brief-grid">${Object.entries(S.doc.brief).map(([k,v])=>field(({audience:'Who is this for?',objective:'What should the viewer understand?',promise:'The core promise',tone:'Voice and tone',constraints:'Boundaries and non-negotiables',references:'References and evidence'})[k],k,v,{area:true})).join('')}</div><div class="row"><span class="content-note grow">This brief is saved with the project revision, not sent to a cloud service.</span><button type="submit" class="primary">Save brief</button></div></form>`;
 case 'narrative':return active(S.doc).map((s,i)=>`<form data-form="narrative" data-id="${e(s.id)}" class="narrative-row">${sceneThumb(s)}<div><div class="row"><h3 class="grow">${i+1}. ${e(s.name)}</h3>${badge(s.role)}</div>${field('Narration text','narration',s.narration,{area:true})}<div class="row"><span class="content-note grow">${durationText(s.duration)} · Text only, no synthesized audio</span><button type="submit" class="outline">Save narration</button></div></div></form>`).join('');
 case 'storyboard':return `<div class="story-grid">${active(S.doc).map((s,i)=>`<article class="story">${sceneThumb(s)}<div class="row"><h3 class="grow">${i+1}. ${e(s.name)}</h3>${badge(s.role)}</div><p>${e(s.narration)}</p><div class="row"><span class="mono grow">${durationText(s.duration)}</span>${button('open-scene','Edit scene',{symbol:'arrow',data:`data-id="${e(s.id)}"`})}</div></article>`).join('')}</div>`;
 case 'alternatives':return S.doc.proposals.length?S.doc.proposals.map(p=>`<article class="proposal"><div class="row"><h3 class="grow">${e(p.title)}</h3>${badge(p.status,p.status==='pending'?'amber':'')}</div><p>${e(p.rationale)}</p><p class="meta">${e(p.provider)} · ${p.changes.length} typed changes · ${e(p.scope)}</p><div class="row">${button('preview-proposal','Compare A / B',{symbol:'proposal',data:`data-id="${e(p.id)}"`})}${p.status==='pending'?button('apply-proposal','Accept proposal',{symbol:'check',cls:'primary',data:`data-id="${e(p.id)}"`})+button('reject-proposal','Reject',{data:`data-id="${e(p.id)}"`}):''}</div></article>`).join(''):`<div class="empty">${icon('proposal')}<h3>Give another direction a fair look.</h3><p>Create a scoped, manual alternative to selected text. External agents can submit the same typed proposals through the Native SDK; no AI provider is connected automatically.</p>${button('new-proposal','Create an alternative',{cls:'primary',symbol:'plus'})}</div>`;
 case 'changes':return `<div class="row list-header"><h2>Branches</h2><div class="grow"></div>${button('fork','Fork current revision',{symbol:'branch'})}</div><div class="settings-list">${S.branches.map(b=>`<div class="integration-row"><div class="grow"><h3>${e(b.name)}</h3><p class="mono">${b.version.revision.slice(0,12)}</p></div>${b.version.resource===S.resource?badge('Current'):button('compare-branch','Compare & merge',{data:`data-resource="${e(b.version.resource)}"`})}</div>`).join('')}</div><div id="branch-comparison"></div><div class="list-header"><h2>Immutable history</h2></div>${S.history.map((r,i)=>`<div class="history-row"><span class="history-marker"></span><div class="grow"><h3>${e(r.operation)}</h3><p class="meta">${e(r.actor)} · ${new Date(r.created).toLocaleString()} · <span class="mono">${r.id.slice(0,10)}</span></p></div>${i===0?badge('Current'):button('restore','Restore as new revision',{symbol:'history',data:`data-id="${e(r.id)}"`})}</div>`).join('')}`;
 case 'dependencies':return `<div class="notice">Canonical Graph: <strong>UNKNOWN — not connected.</strong> These are application-owned relationships, not admitted native evidence.</div><div class="dependency-map">${[['Brief',S.doc.title],['Scene intent',`${active(S.doc).length} scenes, ${S.doc.assets.length} assets`],['Film projection','Typed export; canonical compile required'],['Native artifact','No production receipt']].map(([name,text])=>`<div class="dependency-node"><h3>${name}</h3><p>${e(text)}</p></div>`).join('')}</div><div class="settings-list"><div class="integration-row"><div><h3>Native SDK</h3><p>Canonical TypeScript binding and Rust process bridge, pinned to 4d291de26724.</p></div>${badge('Integrated binding')}</div><div class="integration-row"><div><h3>Effect Conformance</h3><p>No Host-issued operation-bound effect report has been admitted.</p></div>${badge('NOT RUN','amber')}</div><div class="integration-row"><div><h3>Application revision</h3><p class="mono">${e(S.version.revision)}</p></div>${badge('Persisted')}</div></div>`;
 case 'review':return `<div class="list-header row"><h2 class="grow">Anchored discussion</h2>${button('review-frame','Comment',{symbol:'plus'})}</div>${S.doc.reviews.length?S.doc.reviews.map(r=>`<article class="review-item">${icon('review')}<div class="content"><div class="row"><h3 class="grow">${e(r.author)}</h3>${badge(r.status)}</div><p>${e(r.text)}</p><p class="meta">${e(r.sceneId)} · ${r.frame}f · ${e(r.category)} · rev ${e(r.revision.slice(0,8))}</p>${button('jump-review','Go to frame',{data:`data-id="${e(r.id)}"`})}${button('resolve-review',r.status==='open'?'Resolve':'Reopen',{data:`data-id="${e(r.id)}"`})}</div></article>`).join(''):'<p class="content-note">No comments yet. Add a note at the current frame.</p>'}<div class="list-header"><h2>Design checks and editorial advice</h2></div>${S.findings.map(f=>`<article class="review-item">${icon('info')}<div class="content"><h3>${e(f.message)}</h3><p class="meta">${e(f.severity)} · ${e(f.kind)} · ${e(f.coverage)}</p></div></article>`).join('')}`;
 case 'deliver':return `<div class="paper"><h2>Editable handoff</h2><p class="content-note">These exports preserve source intent. They are not an MP4, a native render or a fidelity report.</p><div class="batch-actions">${[['archive','Project archive'],['film','Canonical Film JSON'],['vtt','WebVTT captions'],['srt','SRT captions']].map(([format,label])=>button('export-file',label,{symbol:'download',cls:'outline',data:`data-format="${format}"`})).join('')}</div></div><div class="list-header row"><h2 class="grow">Output profiles</h2>${button('profile','Add profile',{symbol:'plus'})}${button('project-settings','Project settings',{symbol:'settings'})}</div><div class="delivery-profiles">${[{id:'current',name:'Current sequence',width:S.doc.profile.width,height:S.doc.profile.height},...S.doc.deliveries].map(p=>`<div class="profile-option"><span class="aspect-icon ${p.width<p.height?'portrait':p.width===p.height?'square':''}"></span><h3>${e(p.name)}</h3><p class="mono">${p.width} × ${p.height}</p><p class="content-note">${p.id==='current'?'Source dimensions':'Delivery intent; no automatic reflow'}</p></div>`).join('')}</div><div class="list-header"><h2>Production routes</h2></div>${['Motion Canvas','MLT','Blender','Manim'].map(name=>`<div class="integration-row"><div class="grow"><h3>${name}</h3><p>Requires a verified Semwright Host and an installed native runtime.</p></div>${badge('Not connected','amber')}</div>`).join('')}<div class="notice">No empty job is marked complete. Native export, audio mix, effect reports and publish approval are not supplied by the design preview.</div>`;
 case 'assets':return `<div class="notice">Reference imports are limited to 140 KiB per asset in this bounded native profile. Large production media ingestion is not yet connected.</div>${S.doc.assets.length?`<div class="asset-grid">${S.doc.assets.map(a=>{const url=`/api/blob?resource=${encodeURIComponent(S.resource)}&sha256=${a.sha256}`;return `<article class="asset-item">${a.mime.startsWith('image/')?`<img src="${url}" alt="${e(a.name)}">`:a.mime.startsWith('audio/')?`<audio controls preload="metadata" src="${url}" aria-label="${e(a.name)}"></audio>`:`<video controls preload="metadata" src="${url}" aria-label="${e(a.name)}"></video>`}<h3>${e(a.name)}</h3><p>${e(a.mime)} · ${(a.bytes/1024).toFixed(1)} KiB</p><p class="content-note">${e(a.license)} · ${e(a.provenance)}</p>${button('place-asset','Place in scene',{symbol:'plus',data:`data-id="${e(a.id)}"`})}</article>`;}).join('')}</div>`:'<div class="empty"><h3>Bring your references into the sequence.</h3><p>Import an image, audio or video reference. Provenance and licensing travel with the project.</p></div>'}`;
 case 'captions':return `<div class="paper">${S.doc.captions.map(c=>`<div class="review-item"><span class="mono">${c.start}–${c.end}f</span><div class="grow"><p>${e(c.text)}</p><p class="meta">${e(c.language)}</p></div>${button('edit-caption','Edit',{data:`data-id="${e(c.id)}"`})}${ib('remove-caption','archive','Remove caption from current revision',`data-id="${e(c.id)}"`)}</div>`).join('')}</div>`;
 default:return '<div class="empty"><h3>Workspace unavailable</h3></div>';
 }
}
function renderComparison(){
 const node=document.querySelector('#branch-comparison');if(!node||!S.compare)return;
 node.innerHTML=`<div class="paper"><h2>Compare ${e(S.compare.right.resource.split('@')[1])}</h2><p class="content-note">${S.compare.changes.length} changes · ${S.compare.conflicts.length} conflicts. Source revision is checked again at merge time.</p><form data-form="merge"><table class="change-table"><thead><tr><th>Path</th><th>Current</th><th>Source</th></tr></thead><tbody>${S.compare.changes.slice(0,80).map(c=>`<tr><td class="mono">${e(c.path)}</td><td>${e(JSON.stringify(c.before)?.slice(0,140))}</td><td>${e(JSON.stringify(c.after)?.slice(0,140))}</td></tr>`).join('')}</tbody></table>${S.compare.conflicts.map(c=>field(c.path,c.path,'',{options:[['','Choose a resolution'],['left','Keep current'],['right','Use source']]})).join('')}<button type="submit" class="primary">Merge reviewed changes</button></form></div>`;
}
let dialogSubmit=null,dialogReturnFocus=null;
const undoStacks=new Map(),redoStacks=new Map();
function showDialog(title,body,{submit='Save',onSubmit=null,wide=false}={}){
 pause();const modal=document.querySelector('#modal');if(modal.open)modal.close();dialogReturnFocus=document.activeElement;dialogSubmit=onSubmit;
 modal.classList.toggle('wide',wide);modal.innerHTML=`<form data-form="dialog"><div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2>${ib('close-dialog','close','Close dialog')}</div><div class="dialog-body">${body}<p id="dialog-error" role="alert"></p></div><div class="dialog-foot">${button('close-dialog',onSubmit?'Cancel':'Close')}${onSubmit?`<button class="primary" type="submit">${e(submit)}</button>`:''}</div></form>`;modal.showModal();
}
function closeDialog(){document.querySelector('#modal').close();dialogSubmit=null;dialogReturnFocus?.focus?.();}
function formValues(form){return Object.fromEntries(new FormData(form));}
const numberFields=['x','y','width','height','rotation','opacity','fontSize','weight','duration','start','end','frame','value'];
function typed(values){for(const k of numberFields)if(k in values)values[k]=Number(values[k]);return values;}
function newObject(kind='text',extra={}){return {id:uid('obj'),kind,name:kind==='text'?'New title':`New ${kind}`,x:120,y:160,width:kind==='text'?780:180,height:kind==='text'?100:180,rotation:0,opacity:1000,fill:'#b7d7a0',text:kind==='text'?'Make the next frame matter.':'',fontSize:64,weight:500,keyframes:[],archived:false,...extra};}
function newScene(){return {id:uid('scene'),name:'A new scene',role:'mechanism',duration:180,renderer:'motion_canvas',background:scene().background,narration:'',claimStatus:'unreviewed',objects:[newObject()],archived:false};}
function openProjectDialog(){showDialog('Projects',`<div class="command-list">${S.projects.map(p=>button('open-project',e(p.title),{symbol:'film',data:`data-resource="${e(p.resource)}"`})).join('')}</div><div class="batch-actions">${button('new-project','Create project',{symbol:'plus',cls:'primary'})}${button('import-project','Import project archive',{symbol:'folder'})}${button('project-settings','Project settings',{symbol:'settings'})}</div>`);}
function createProjectDialog(){showDialog('Create a sequence',`${field('Project title','title','Untitled sequence')}${field('Starting point','template','product',{options:[['product','Product explainer'],['lesson','Educational story'],['brand','Brand study'],['','Blank sequence']]})}<p class="content-note">The examples use original synthetic text and shapes. No voiceover or customer content is included.</p>`,{submit:'Create project',onSubmit:async v=>{const p={title:v.title};if(v.template)p.template=v.template;await mutate('project.create',p,{expected:S.workspaceVersion,resource:S.resource,followCreated:true});}});}
function settingsDialog(){showDialog('Project settings',`${field('Title','title',S.doc.title)}${field('Description','description',S.doc.description,{area:true})}<div class="field-grid">${field('Width','width',S.doc.profile.width,{type:'number',min:240,max:7680})}${field('Height','height',S.doc.profile.height,{type:'number',min:240,max:7680})}${field('FPS numerator','fpsNum',S.doc.profile.fps.num,{type:'number',min:1})}${field('FPS denominator','fpsDen',S.doc.profile.fps.den,{type:'number',min:1})}</div><p class="content-note">Frame numbers are preserved when the rate changes. This changes playback duration; it does not silently retime captions.</p>`,{onSubmit:v=>mutate('document.edit',{title:v.title,description:v.description,profile:{width:Number(v.width),height:Number(v.height),fps:{num:Number(v.fpsNum),den:Number(v.fpsDen)}}})});}
function captionDialog(id=null){const c=S.doc.captions.find(x=>x.id===id)??{id:uid('caption'),start:sceneStart(S.sceneId),end:sceneStart(S.sceneId)+scene().duration,text:'',language:'en'};showDialog(id?'Edit caption':'Add caption',`${field('Caption text','text',c.text,{area:true})}<div class="field-grid">${field('Start frame','start',c.start,{type:'number',min:0,max:total(S.doc)-1})}${field('End frame (exclusive)','end',c.end,{type:'number',min:1,max:total(S.doc)})}${field('Language','language',c.language)}</div>`,{onSubmit:v=>mutate('caption.set',{caption:{...c,...typed(v)}})});}
function reviewDialog(){showDialog('Comment on this frame',`<p class="content-note">${e(scene().name)} · ${timecode(S.frame,S.doc.profile.fps)} · rev ${S.version.revision.slice(0,8)}</p>${field('Comment','text','',{area:true})}${field('Category','category','comment',{options:[['comment','Comment'],['creative-advice','Creative advice'],['technical','Technical observation']]})}`,{submit:'Add comment',onSubmit:v=>mutate('review.add',{id:uid('review'),sceneId:S.sceneId,objectId:S.objectId,frame:S.frame,text:v.text,category:v.category})});}
function proposalDialog(){const o=selected();if(!o||o.kind!=='text'){toast('Select a text layer first. Use Canvas → Layers to choose one.',true);S.workspace='canvas';S.inspectorTab='layers';render();return;}const sceneId=S.sceneId,objectId=o.id;showDialog('Propose a text alternative',`${field('Proposal title','title','A different direction')}${field('Why this change?','rationale','',{area:true})}${field('Alternative text','text',o.text,{area:true})}<p class="content-note">Scope: ${e(o.name)} only. This is a manual proposal. Nothing changes until you accept it.</p>`,{submit:'Save proposal',onSubmit:v=>mutate('proposal.create',{id:uid('proposal'),title:v.title,rationale:v.rationale,scope:objectId,provider:'manual-editor',constraints:['Only update selected text; preserve composition and timing.'],changes:[{operation:'object.update',parameters:{sceneId,objectId,changes:{text:v.text}}}]})});}
function previewProposal(id){const p=S.doc.proposals.find(x=>x.id===id),candidate=structuredClone(S.doc);if(!p)return;let supported=true;for(const c of p.changes){if(c.operation==='object.update'){const s=candidate.scenes.find(x=>x.id===c.parameters.sceneId),o=s?.objects.find(x=>x.id===c.parameters.objectId);if(o)Object.assign(o,c.parameters.changes);else supported=false;}else if(c.operation==='scene.update'){const s=candidate.scenes.find(x=>x.id===c.parameters.sceneId);if(s)Object.assign(s,c.parameters.changes);else supported=false;}else supported=false;}
 const targetId=p.changes.find(c=>c.parameters.sceneId)?.parameters.sceneId??S.sceneId,a=S.doc.scenes.find(s=>s.id===targetId),b=candidate.scenes.find(s=>s.id===targetId);
 showDialog(p.title,`${supported&&a&&b?`<div class="compare-grid"><section><h3>A · Current design</h3>${sceneSvg(S.doc,a,60,{resource:S.resource})}</section><section><h3>B · Proposed design</h3>${sceneSvg(candidate,b,60,{resource:S.resource})}</section></div>`:'<p class="notice">This proposal includes operations outside the A/B preview subset. Review the complete typed changes below before acceptance.</p>'}<p>${e(p.rationale)}</p><details><summary>Exact typed changes</summary><pre>${e(JSON.stringify(p.changes,null,2))}</pre></details><p class="content-note">These are browser design approximations, not native render comparisons.</p>`,{wide:true});}
function keyframeDialog(){const o=selected();if(!o)return;showDialog('Add a typed keyframe',`<div class="field-grid">${field('Scene frame','frame',Math.max(0,Math.min(scene().duration-1,S.frame-sceneStart(S.sceneId))),{type:'number',min:0,max:scene().duration-1})}${field('Property','property','opacity',{options:['opacity','x','y','width','height','rotation']})}${field('Value','value',o.opacity,{type:'number',min:-16384,max:16384})}${field('Interpolation','easing','linear',{options:['linear','hold','ease-in-out']})}</div>`,{onSubmit:v=>mutate('keyframe.set',{sceneId:S.sceneId,objectId:o.id,keyframe:typed(v)})});}
function download(name,value,type='application/json'){const data=typeof value==='string'?value:JSON.stringify(value,null,2);const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportFile(format){const value=await call('document.export',{resource:S.resource,format},S.version);const title=S.doc.title.replace(/[^a-z0-9_-]+/gi,'-').slice(0,60)||'sequence';if(format==='srt'||format==='vtt')download(`${title}.${format}`,value.text,'text/plain');else download(`${title}.${format==='film'?'film':'sequencewright'}.json`,format==='film'?value.film:value);toast('Exported source data. No native media render was claimed.');}
function chooseFile(accept,handler,maxBytes){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>maxBytes)throw new Error(`File exceeds the ${(maxBytes/1024).toFixed(0)} KiB limit for this profile.`);await handler(file);}catch(error){toast(error.message,true);}};input.click();}
function importProject(){chooseFile('.json',async file=>{const value=JSON.parse(await file.text());if(value.schema!=='sequencewright/archive/1')throw new Error('Choose a Sequencewright project archive.');await mutate('project.import',{document:value.document,blobs:value.blobs??[]},{expected:S.workspaceVersion,followCreated:true});},240*1024);}
function importAsset(){chooseFile('image/png,image/jpeg,image/webp,audio/wav,audio/mpeg,video/mp4',async file=>{const bytes=new Uint8Array(await file.arrayBuffer()),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');let binary='';for(const n of bytes)binary+=String.fromCharCode(n);const mime=file.type==='audio/x-wav'?'audio/wav':file.type;showDialog('Asset provenance',`${field('Asset name','name',file.name)}${field('License or usage permission','license','')}${field('Source and provenance','provenance','',{area:true})}<p class="content-note">${file.size} bytes · ${e(mime)}. Imported bytes stay in this application database.</p>`,{submit:'Import reference',onSubmit:v=>mutate('asset.attach',{asset:{id:uid('asset'),name:v.name,sha256:digest,mime,bytes:file.size,license:v.license,provenance:v.provenance},blob:{base64:btoa(binary),mime}})});},140*1024);}
function palette(){showDialog('Commands',`<input id="command-filter" type="search" placeholder="Find a workspace or action…" aria-label="Find a command" autofocus><div class="command-list">${[...tabs.map(([id,label,symbol])=>button('workspace',label,{symbol,data:`data-workspace="${id}"`})),button('assets','Assets',{symbol:'folder'}),button('captions','Captions',{symbol:'caption'}),button('inspector-mobile','Open inspector',{symbol:'settings'}),button('new-project','New project',{symbol:'plus'}),button('import-project','Import project archive',{symbol:'folder'}),button('project-settings','Project settings',{symbol:'settings'}),button('theme','Switch theme',{symbol:'sun'})].join('')}</div>`);}
function help(){showDialog('Keyboard shortcuts',`<div class="shortcut-grid">${[['Space','Play / pause'],['J / K / L','Reverse / stop / forward'],['← / →','Previous / next frame'],['Shift + ← / →','Jump ten frames'],['Ctrl / ⌘ + K','Open commands'],['Ctrl / ⌘ + Z','Restore previous local edit'],['Ctrl / ⌘ + Shift + Z','Redo a restored local edit'],['Escape','Close dialog / stop playback']].map(([key,label])=>`<span class="key">${e(key)}</span><span>${label}</span>`).join('')}</div><p class="content-note">Text fields keep their normal keyboard behavior. History restoration never deletes prior revisions.</p>`);}
function pause(){S.playing=false;cancelAnimationFrame(anim);document.querySelector('[data-action="play"]')?.replaceChildren();const b=document.querySelector('[data-action="play"]');if(b)b.innerHTML=icon('play');}
function play(){if(S.playing){pause();return;}S.playing=true;lastTime=performance.now();remainder=0;const b=document.querySelector('[data-action="play"]');if(b)b.innerHTML=icon('pause');anim=requestAnimationFrame(tick);}
function tick(now){if(!S.playing)return;const elapsed=Math.min(200,now-lastTime);lastTime=now;remainder+=elapsed*S.doc.profile.fps.num/S.doc.profile.fps.den/1000*S.playRate;const steps=Math.floor(remainder);remainder-=steps;if(steps){const next=S.frame+steps*S.playDirection;if(next<0||next>=total(S.doc)){S.frame=S.playDirection>0?total(S.doc)-1:0;pause();}else S.frame=next;const current=atFrame(S.doc,S.frame);if(current.scene.id!==S.sceneId){S.sceneId=current.scene.id;S.objectId=null;const wasPlaying=S.playing;render();S.playing=wasPlaying;}updatePlayhead(true);}if(S.playing)anim=requestAnimationFrame(tick);}
function updatePlayhead(draw=false){if(!S.doc)return;const t=document.querySelector('#current-time');if(t)t.textContent=timecode(S.frame,S.doc.profile.fps);const body=document.querySelector('#timeline-body'),p=document.querySelector('#playhead');if(body&&p){const label=body.querySelector('.track-label');p.style.left=`${(label?.offsetWidth??110)+S.frame*Number(body.dataset.px)}px`;}
 if(draw){const c=document.querySelector('#canvas');if(c)c.innerHTML=sceneSvg(S.doc,scene(),S.frame-sceneStart(S.sceneId),{selected:S.objectId,guides:S.guides,resource:S.resource,interactive:true});}
}
async function undoEdit(redo=false){const from=redo?redoStacks:undoStacks,to=redo?undoStacks:redoStacks,list=from.get(S.resource)??[];if(!list.length){if(!redo&&S.history[1])return mutate('history.restore',{revision:S.history[1].id});toast('No local edit to restore. Use Changes for the full revision history.');return;}const revision=list.at(-1),before=S.version.revision;await mutate('history.restore',{revision},{track:false});list.pop();from.set(S.resource,list);to.set(S.resource,[...(to.get(S.resource)??[]),before]);}
async function onAction(action,el){
 if(action==='close-dialog'){closeDialog();return;}
 if(['workspace','open-project','new-project','project-settings','palette','assets','captions','inspector-mobile','theme','import-project'].includes(action)&&document.querySelector('#modal').open)closeDialog();
 switch(action){
 case 'workspace':pause();S.workspace=el.dataset.workspace;render();break;
 case 'project-menu':openProjectDialog();break;case 'new-project':createProjectDialog();break;
 case 'open-project':closeDialog();await load(el.dataset.resource);break;case 'project-settings':settingsDialog();break;
 case 'select-scene':selectScene(el.dataset.id);break;case 'open-scene':S.workspace='canvas';selectScene(el.dataset.id);break;
 case 'select-object':S.objectId=el.dataset.id;S.inspectorTab='object';render();break;
 case 'inspector-object':S.inspectorTab='object';render();break;case 'inspector-scene':S.inspectorTab='scene';render();break;case 'inspector-layers':S.inspectorTab='layers';render();break;
 case 'inspector-mobile':showDialog('Inspector',inspector(),{wide:true});break;
 case 'add-scene':{const next=newScene();await mutate('scene.add',{scene:next,afterId:S.sceneId});selectScene(next.id);break;}
 case 'add-text':case 'add-rect':case 'add-circle':{const o=newObject(action==='add-text'?'text':action==='add-circle'?'circle':'rectangle');await mutate('object.add',{sceneId:S.sceneId,object:o});S.objectId=o.id;S.inspectorTab='object';render();break;}
 case 'select-tool':S.workspace='canvas';render();break;case 'guides':S.guides=!S.guides;render();break;case 'zoom':S.scale=S.scale===100?125:S.scale===125?75:100;render();break;
 case 'fullscreen':{const c=document.querySelector('.canvas-section');if(document.fullscreenElement)await document.exitFullscreen();else await c?.requestFullscreen();break;}
 case 'play':play();break;case 'speed':S.playRate=S.playRate===1?1.5:S.playRate===1.5?2:1;render();break;
 case 'previous-scene':case 'next-scene':{const scenes=active(S.doc),i=scenes.findIndex(s=>s.id===S.sceneId);selectScene(scenes[Math.max(0,Math.min(scenes.length-1,i+(action==='next-scene'?1:-1)))].id);break;}
 case 'theme':S.theme=S.theme==='dark'?'light':'dark';localStorage.setItem('sw:theme',S.theme);render();break;
 case 'palette':palette();break;case 'help':help();break;case 'reload':await load();break;case 'undo':await undoEdit();break;case 'redo':await undoEdit(true);break;
 case 'assets':case 'captions':case 'review':case 'deliver':pause();S.workspace=action;render();break;
 case 'keyframe':keyframeDialog();break;case 'remove-keyframe':await mutate('keyframe.remove',{sceneId:S.sceneId,objectId:S.objectId,frame:Number(el.dataset.frame),property:el.dataset.property});break;
 case 'archive-object':if(selected())await mutate('object.archive',{sceneId:S.sceneId,objectId:S.objectId,archived:true});break;
 case 'lock':showDialog('Protect this selection',field('Reason','reason','Preserve this editorial decision'),{submit:'Lock selection',onSubmit:v=>mutate('lock.set',{scope:selected()?.id??S.sceneId,reason:v.reason})});break;
 case 'unlock':await mutate('lock.release',{scope:selected()?.id??S.sceneId});break;
 case 'new-proposal':proposalDialog();break;case 'preview-proposal':previewProposal(el.dataset.id);break;
 case 'apply-proposal':await mutate('proposal.apply',{proposalId:el.dataset.id});break;case 'reject-proposal':await mutate('proposal.reject',{proposalId:el.dataset.id});break;
 case 'fork':showDialog('Fork current revision',`${field('Branch name','name','alternative')}<p class="content-note">The new branch receives its own native identity. Main is preserved.</p>`,{submit:'Create branch',onSubmit:v=>mutate('branch.fork',{name:v.name},{followCreated:true})});break;
 case 'compare-branch':S.compare=await call('branch.compare',{resource:S.resource,other:el.dataset.resource},S.version);renderComparison();break;
 case 'restore':{const rev=el.dataset.id;showDialog('Restore an earlier state',`<p>A new revision will restore ${e(rev.slice(0,12))}. All history and current protection locks are preserved.</p>`,{submit:'Restore as new revision',onSubmit:()=>mutate('history.restore',{revision:rev})});break;}
 case 'review-frame':reviewDialog();break;case 'resolve-review':{const r=S.doc.reviews.find(x=>x.id===el.dataset.id);await mutate('review.resolve',{reviewId:r.id,resolved:r.status==='open'});break;}
 case 'jump-review':{const r=S.doc.reviews.find(x=>x.id===el.dataset.id);S.workspace='canvas';S.frame=r.frame;selectScene(r.sceneId,{keepFrame:true});break;}
 case 'add-caption':captionDialog();break;case 'edit-caption':captionDialog(el.dataset.id);break;case 'remove-caption':await mutate('caption.remove',{captionId:el.dataset.id});break;
 case 'export-file':await exportFile(el.dataset.format);break;case 'import-project':importProject();break;case 'import-asset':importAsset();break;
 case 'place-asset':{const a=S.doc.assets.find(x=>x.id===el.dataset.id),o=newObject(a.mime.startsWith('image/')?'image':a.mime.startsWith('video/')?'video':'audio',{name:a.name,assetId:a.id,width:640,height:360});await mutate('object.add',{sceneId:S.sceneId,object:o});S.workspace='canvas';S.objectId=o.id;render();break;}
 case 'profile':showDialog('Add a delivery profile',`${field('Profile name','name','Vertical story')}<div class="field-grid">${field('Width','width',1080,{type:'number',min:240,max:7680})}${field('Height','height',1920,{type:'number',min:240,max:7680})}${field('Language','language','en')}</div>`,{onSubmit:v=>mutate('delivery.profile',{id:uid('profile'),name:v.name,width:Number(v.width),height:Number(v.height),language:v.language,captions:true})});break;
 default:toast('This action is not available in the current workspace.',true);
 }
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();Promise.resolve(onAction(button.dataset.action,button)).catch(error=>toast(error.message,true));});
document.addEventListener('submit',async event=>{
 const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(S.busy)return;const kind=form.dataset.form,values=typed(formValues(form));const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;
 try{
  if(kind==='dialog'){if(dialogSubmit){await dialogSubmit(values);closeDialog();}}
  else if(kind==='object')await mutate('object.update',{sceneId:S.sceneId,objectId:S.objectId,changes:values});
  else if(kind==='scene')await mutate('scene.update',{sceneId:S.sceneId,changes:values});
  else if(kind==='brief')await mutate('brief.update',values);
  else if(kind==='narrative')await mutate('scene.update',{sceneId:form.dataset.id,changes:{narration:values.narration}});
  else if(kind==='merge'){if(Object.values(values).some(v=>!['left','right'].includes(v)))throw new Error('Choose a resolution for every conflict.');await mutate('branch.merge',{source:S.compare.right.resource,sourceVersion:S.compare.right,resolutions:values});S.compare=null;render();}
 }catch(error){const message=document.querySelector('#dialog-error');if(document.querySelector('#modal').open&&message)message.textContent=error.message;else toast(error.message,true);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('change',event=>{const input=event.target,key=input.dataset.change;if(!key)return;Promise.resolve().then(async()=>{if(key==='project'||key==='branch'){S.compare=null;await load(input.value);}else if(key==='timeline-zoom'){S.timelineZoom=Number(input.value);render();}}).catch(error=>toast(error.message,true));});
document.addEventListener('input',event=>{if(event.target.id==='scene-search'){const q=event.target.value.toLowerCase();document.querySelectorAll('.scene-item').forEach(item=>item.hidden=!item.getAttribute('aria-label').toLowerCase().includes(q));}if(event.target.id==='command-filter'){const q=event.target.value.toLowerCase();document.querySelectorAll('#modal .command-list button').forEach(item=>item.hidden=!item.textContent.toLowerCase().includes(q));}});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){pause();return;}
 if(event.target.matches('input,textarea,select,[contenteditable=true]'))return;
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();palette();return;}
 if(document.querySelector('#modal').open)return;
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();undoEdit(event.shiftKey).catch(error=>toast(error.message,true));return;}
 if(event.target.matches('[data-resize]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const side=event.target.dataset.resize,prop=side==='timeline'?'--timeline':side==='left'?'--left':'--right',current=parseInt(getComputedStyle(document.documentElement).getPropertyValue(prop)),delta=['ArrowLeft','ArrowDown'].includes(event.key)?-10:10;document.documentElement.style.setProperty(prop,Math.max(140,Math.min(500,current+delta))+'px');return;}
 if(event.key===' '){event.preventDefault();play();}else if(event.key==='k'){pause();}else if(event.key==='j'||event.key==='l'){S.playDirection=event.key==='j'?-1:1;if(!S.playing)play();}else if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();pause();S.frame=Math.max(0,Math.min(total(S.doc)-1,S.frame+(event.key==='ArrowRight'?1:-1)*(event.shiftKey?10:1)));const at=atFrame(S.doc,S.frame);S.sceneId=at.scene.id;render();}
});
document.addEventListener('dragstart',event=>{const item=event.target.closest('[data-scene-drag]');if(item){pause();event.dataTransfer.setData('application/x-sequencewright-scene',item.dataset.sceneDrag);event.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',event=>{if(event.target.closest('[data-scene-drag]')&&event.dataTransfer.types.includes('application/x-sequencewright-scene')){event.preventDefault();event.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',event=>{const item=event.target.closest('[data-scene-drag]'),from=event.dataTransfer.getData('application/x-sequencewright-scene');if(!item||!from)return;event.preventDefault();const to=item.dataset.sceneDrag;if(from===to)return;const order=S.doc.scenes.map(s=>s.id).filter(id=>id!==from);order.splice(order.indexOf(to),0,from);mutate('scene.reorder',{order}).catch(()=>{});});
document.addEventListener('pointerdown',event=>{
 if(event.button!==0||!S.doc||S.busy)return;
 const hit=event.target.closest('[data-object]'),resize=event.target.closest('[data-resize]'),trim=event.target.closest('[data-trim]'),scrub=event.target.closest('[data-scrub]');
 if(hit){pause();event.preventDefault();const o=scene().objects.find(x=>x.id===hit.dataset.object),svg=document.querySelector('#canvas svg');drag={kind:'object',id:o.id,sceneId:S.sceneId,x:event.clientX,y:event.clientY,startX:o.x,startY:o.y,scale:S.doc.profile.width/svg.getBoundingClientRect().width,dx:0,dy:0,element:hit.parentElement};S.objectId=o.id;}
 else if(resize){event.preventDefault();const side=resize.dataset.resize,prop=side==='timeline'?'--timeline':side==='left'?'--left':'--right';drag={kind:'resize',prop,side,x:event.clientX,y:event.clientY,start:parseInt(getComputedStyle(document.documentElement).getPropertyValue(prop))};}
 else if(trim){event.preventDefault();pause();const s=S.doc.scenes.find(x=>x.id===trim.dataset.trim);drag={kind:'trim',sceneId:s.id,start:s.duration,x:event.clientX,px:Number(document.querySelector('#timeline-body').dataset.px),duration:s.duration,element:trim.parentElement};}
 else if(scrub){event.preventDefault();pause();drag={kind:'scrub',left:scrub.getBoundingClientRect().left,px:Number(document.querySelector('#timeline-body').dataset.px)};scrubTo(event.clientX);}
});
function scrubTo(x){S.frame=Math.max(0,Math.min(total(S.doc)-1,Math.round((x-drag.left)/drag.px)));const at=atFrame(S.doc,S.frame);S.sceneId=at.scene.id;updatePlayhead(true);}
window.addEventListener('pointermove',event=>{if(!drag)return;
 if(drag.kind==='object'){drag.dx=Math.round((event.clientX-drag.x)*drag.scale);drag.dy=Math.round((event.clientY-drag.y)*drag.scale);drag.element.style.translate=`${drag.dx}px ${drag.dy}px`;}
 else if(drag.kind==='resize'){const delta=drag.side==='timeline'?drag.y-event.clientY:drag.side==='right'?drag.x-event.clientX:event.clientX-drag.x;document.documentElement.style.setProperty(drag.prop,Math.max(140,Math.min(500,drag.start+delta))+'px');}
 else if(drag.kind==='trim'){drag.duration=Math.max(1,Math.min(216000,drag.start+Math.round((event.clientX-drag.x)/drag.px)));drag.element.style.width=`${Math.max(20,drag.duration*drag.px-3)}px`;}
 else if(drag.kind==='scrub')scrubTo(event.clientX);
});
window.addEventListener('pointerup',async()=>{const d=drag;drag=null;if(!d)return;try{if(d.kind==='object'){if(Math.abs(d.dx)+Math.abs(d.dy)>1)await mutate('object.update',{sceneId:d.sceneId,objectId:d.id,changes:{x:d.startX+d.dx,y:d.startY+d.dy}});S.inspectorTab='object';render();}else if(d.kind==='trim'&&d.duration!==d.start){await mutate('scene.update',{sceneId:d.sceneId,changes:{duration:d.duration}});}else if(d.kind==='scrub')render();}catch(error){render();toast(error.message,true);}});
window.addEventListener('pointercancel',()=>{drag=null;render();});
window.addEventListener('blur',()=>{pause();if(drag){drag=null;render();}});
window.addEventListener('beforeunload',event=>{if(S.busy){event.preventDefault();event.returnValue='A change is still being saved.';}});
function showStaleBanner(){S.stale=true;if(document.querySelector('.error-banner'))return;const banner=document.createElement('div');banner.className='error-banner';banner.innerHTML=`<span>A newer revision exists. Review the current version before applying your next change.</span>${button('reload','Reload current revision',{symbol:'retry'})}`;document.querySelector('#app').append(banner);}
async function bootstrap(){
 try{const response=await fetch('/api/session');if(!response.ok)throw new Error('Could not open a local studio session. Reload the loopback URL.');const session=await response.json();S.csrf=session.csrf;try{await load();}catch(error){if(error.code!=='NotFound')throw error;const projects=await call('project.list');if(!projects.items.length)throw new Error('No project is available in this workspace.');await load(projects.items[0].resource);}
 setInterval(async()=>{if(S.busy||S.stale||!S.doc||document.hidden)return;try{const current=await call('document.read',{resource:S.resource});if(current.version.revision!==S.version.revision)showStaleBanner();}catch(error){setSaveState('Connection interrupted');}},6000);
 }catch(error){document.querySelector('#app').innerHTML=`<main class="startup-error"><h1>Sequencewright could not open this workspace.</h1><p>${e(error.message)}</p><p>Keep your database intact. Check the local server, then reload this page.</p></main>`;console.error(error);}
}
bootstrap();
